import{_ as n,l as r,o as e,c as s,v as o,p as l,x as i,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"调查预期数据","description":"","frontmatter":{"title":"调查预期数据","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/survey-expectations.md","filePath":"econ/survey-expectations.md","lastUpdated":1789023840000}'),c={name:"econ/survey-expectations.md"};function A(h,a,m,_,u,B){const t=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="调查预期数据" tabindex="-1">调查预期数据 <a class="header-anchor" href="#调查预期数据" aria-label="Permalink to &quot;调查预期数据&quot;">​</a></h1><div class="epigraph"><p>结构预期最终要面对人报出来的数字：均值偏差、反应不足或过度、截面分歧，都是模型的矩，不是装饰。</p><footer>—— Coibion and Gorodnichenko, Information Rigidity and the Expectations Formation Process, AER 2015；Michigan、SPF、Consensus</footer></div><p><a href="/econ/uncertainty-shocks">上一课</a>给了方差对象。信念的可测对应是调查。本课缺口是把学习、粘性信息、疏忽、诊断性、新闻<strong>对着数据</strong>。不重推各模型公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RE 加完全信息：预测误差对信息集不可预测，预测修订的回归有精确约束。Coibion–Gorodnichenko：用 SPF 修订对未来误差回归，发现反应不足（信息刚性）。另一端：有的序列过冲。分歧（截面方差）随冲击升，粘性信息与疏忽都能造分歧，诊断性主要造均值偏误。缺口是：本单元前几课的装置现在有可拒绝的矩，而不是并存的故事。</p><p><span class="marginnote">Coibion and Gorodnichenko, <em>AER</em> 2015；<em>JPE</em> 2012。Mankiw, Reis and Wolfers 的分歧。Andrade–Le Bihan、Dovern 等。Michigan 消费者、ECB SPF、专业预测商。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>矩：（i）误差对滞后误差、对修订的回归；（ii）分歧与波动的共动；（iii）家庭 vs 专家的差距；（iv）对政策公告的即时修订（接高频）。估计：用这些矩校准 \\(\\lambda\\)、\\(\\kappa\\)、\\(\\theta\\)、学习增益，而不是只用宏观 IRF。注意：调查不是激励相容的市场预测，噪声与选择性回答存在；市场隐含（通胀掉期）是另一套，含风险价格。</p>',8)),(e(),l(p,null,{default:i(()=>[E(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUR%5B%22%E8%B0%83%E6%9F%A5%E5%9D%87%E5%80%BC%20%2F%20%E5%88%86%E6%AD%A7%22%5D%20--%3E%20RIG%5B%22%E4%BF%AE%E8%AE%A2-%E8%AF%AF%E5%B7%AE%3A%20%E5%88%9A%E6%80%A7%22%5D%0A%20%20SUR%20--%3E%20DIS%5B%22%E5%88%86%E6%AD%A7%E5%8A%A8%E6%80%81%22%5D%0A%20%20RIG%20--%3E%20MOD%5B%22%E7%B2%98%E6%80%A7%E4%BF%A1%E6%81%AF%20%2F%20%E7%96%8F%E5%BF%BD%20%2F%20%E5%AD%A6%E4%B9%A0%22%5D%0A%20%20DIS%20--%3E%20MOD%0A%20%20BIAS%5B%22%E7%B3%BB%E7%BB%9F%E5%81%8F%E8%AF%AF%22%5D%20--%3E%20DIAG%5B%22%E8%AF%8A%E6%96%AD%E6%80%A7%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>HANK：家庭调查的收入与通胀预期直接进高 MPC 行为，比专家 SPF 更相关，数据也更吵。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把不可见的 \\(\\mathbb{E}_t\\) 换成可观测的预报。拒绝完全信息 RE 并不自动选出唯一替代：粘性信息、疏忽、有限层级、诊断性都能匹配部分矩，需联合看修订、分歧与过冲。政策：若家庭预期不更新，泰勒规则的预期通道弱，收入通道（HANK）相对更重要——与沟通课接头。</p><p><span class="marginnote">预测市场与调查的差别：风险中性概率 vs 平均信念。本课以调查为主，不把期权隐含密度当同一对象。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不清洗每一项调查微观数据。不把选举民调当宏观预期。资产分析师盈利预测的行为金融文献点到为止。下一课才把央行如何移动这些数字写成政策。</p><p>后课默认：预期模型必须报告调查矩（修订、分歧、家庭–专家差）。下一课：沟通作为移动信念的工具。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调查提供误差可预测性、修订与分歧等可拒绝矩。</li><li>信息刚性是常见结果，但不唯一对应某一模型。</li><li>家庭调查对 HANK 更相关，噪声更大。</li><li>出处：Coibion and Gorodnichenko, <em>AER</em> 2015。</li></ul>',9))])}const F=n(c,[["render",A]]);export{D as __pageData,F as default};
